import pytest

from csvledger.csvio import quote_value, read_records
from csvledger.errors import LedgerError

REQ = ["date", "description", "amount"]


def write(tmp_path, content, name="t.csv"):
    p = tmp_path / name
    p.write_bytes(content if isinstance(content, bytes) else content.encode("utf-8"))
    return str(p)


def err(path, code=3, req=REQ):
    with pytest.raises(LedgerError) as e:
        list(read_records(path, code, req))
    assert e.value.code == code
    return e.value.message


def test_missing_file(tmp_path):
    p = str(tmp_path / "nope.csv")
    assert err(p, 4) == f"{p}: cannot read file"


def test_invalid_utf8(tmp_path):
    p = write(tmp_path, b"date,description,amount\n\xff\n")
    assert err(p) == f"{p}: not valid UTF-8"


def test_empty_and_bom_only(tmp_path):
    for data in (b"", b"\xef\xbb\xbf"):
        p = write(tmp_path, data)
        assert err(p) == f"{p}: missing header"


def test_blank_first_line(tmp_path):
    p = write(tmp_path, "\ndate,description,amount\n")
    assert err(p) == f"{p}: missing column 'date'"


def test_duplicate_header(tmp_path):
    p = write(tmp_path, "a,b,b,a\n")
    assert err(p, req=["a", "b"]) == f"{p}: duplicate column 'b'"


def test_duplicate_after_strip_lower(tmp_path):
    p = write(tmp_path, "Date, DATE ,description,amount\n")
    assert err(p) == f"{p}: duplicate column 'date'"


def test_duplicate_beats_missing(tmp_path):
    p = write(tmp_path, "x,x\n")
    assert err(p) == f"{p}: duplicate column 'x'"


def test_missing_column_order(tmp_path):
    p = write(tmp_path, "amount\n")
    assert err(p) == f"{p}: missing column 'date'"
    p = write(tmp_path, "date,amount\n")
    assert err(p, 4) == f"{p}: missing column 'description'"


def test_field_count_mismatch(tmp_path):
    p = write(tmp_path, "date,description,amount\n1,2,3\n1,2\n")
    assert err(p) == f"{p}:3: expected 3 fields, got 2"


def test_multiline_quoted_line_num(tmp_path):
    p = write(tmp_path, 'date,description,amount\n1,"a\nb",3\n4,5\n')
    assert err(p) == f"{p}:4: expected 3 fields, got 2"
    p = write(tmp_path, 'date,description,amount\n1,"a\nb",3\n')
    assert list(read_records(p, 3, REQ)) == [
        (3, {"date": "1", "description": "a\nb", "amount": "3"})
    ]


def test_bom_stripped(tmp_path):
    p = write(tmp_path, b"\xef\xbb\xbfdate,description,amount\n1,2,3\n")
    assert list(read_records(p, 3, REQ)) == [
        (2, {"date": "1", "description": "2", "amount": "3"})
    ]


@pytest.mark.parametrize("nl", ["\r\n", "\r"])
def test_crlf_and_cr(tmp_path, nl):
    p = write(tmp_path, nl.join(["date,description,amount", "1,2,3", "4,5,6", ""]))
    assert [n for n, _ in read_records(p, 3, REQ)] == [2, 3]


def test_blank_rows_skipped_and_counted(tmp_path):
    p = write(tmp_path, "date,description,amount\n\n1,2,3\n\n4,5,6\n")
    assert [n for n, _ in read_records(p, 3, REQ)] == [3, 5]


def test_whitespace_only_line_fails_count(tmp_path):
    p = write(tmp_path, "date,description,amount\n   \n")
    assert err(p) == f"{p}:2: expected 3 fields, got 1"


def test_extra_columns_and_strip(tmp_path):
    p = write(tmp_path, " Amount ,x,DATE,Description\n 1 , y , 2026-01-01 , d \n")
    assert list(read_records(p, 3, REQ)) == [
        (2, {"amount": "1", "x": "y", "date": "2026-01-01", "description": "d"})
    ]


def test_header_only_is_valid(tmp_path):
    p = write(tmp_path, "date,description,amount\n")
    assert list(read_records(p, 3, REQ)) == []


def test_late_utf8_error_wins_over_early_row_error(tmp_path):
    p = write(tmp_path, b"date,description,amount\n1,2\n1,2,3\n1,\xff,3\n")
    assert err(p) == f"{p}: not valid UTF-8"


def test_malformed_csv(tmp_path):
    p = write(tmp_path, "date,description,amount\n1,2,3\0\n")
    try:
        rows = list(read_records(p, 4, REQ))
    except LedgerError as e:
        assert e.code == 4 and e.message == f"{p}:2: malformed CSV"
    else:
        pytest.skip("this Python accepts NUL in fields")


def test_quote_value():
    assert quote_value("a\r\nb") == "a\\r\\nb"
