RULES_ERROR = 4


class Rule(NamedTuple):
    category: str
    type: str
    pattern: str
    priority: int
    regex: Optional[Pattern]


def load_rules(path_str):
    rules = []
    for line, row in read_records(
        path_str, RULES_ERROR, ["category", "type", "pattern", "priority"]
    ):

        def fail(msg):
            return LedgerError(RULES_ERROR, f"{path_str}:{line}: {msg}")

        category, rtype = row["category"], row["type"]
        pattern, priority = row["pattern"], row["priority"]
        if not category:
            raise fail("empty category")
        if rtype not in ("contains", "regex"):
            raise fail(f"invalid type '{quote_value(rtype)}'")
        if not pattern:
            raise fail("empty pattern")
        if not re.fullmatch(r"-?[0-9]+", priority):
            raise fail(f"invalid priority '{quote_value(priority)}'")
        compiled = None
        if rtype == "regex":
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
            except re.error:
                raise fail(f"invalid regex '{quote_value(pattern)}'") from None
        rules.append(Rule(category, rtype, pattern, int(priority), compiled))
    return rules


def categorize(description, rules):
    best = None
    folded = description.casefold()
    for rule in rules:
        if best is not None and rule.priority <= best.priority:
            continue
        if rule.type == "contains":
            hit = rule.pattern.casefold() in folded
        else:
            hit = rule.regex.search(description) is not None
        if hit:
            best = rule
    return best.category if best else "Uncategorized"

