import datetime
import re
from dataclasses import dataclass
from decimal import Decimal

from csvledger.csvio import quote_value, read_records
from csvledger.errors import LedgerError
from csvledger.money import parse_amount

DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


@dataclass(frozen=True)
class Transaction:
    date: datetime.date
    date_text: str
    description: str
    amount: Decimal


def load_transactions(path_str):
    result = []
    for line, rec in read_records(path_str, 3, ("date", "description", "amount")):
        date_text = rec["date"]
        try:
            if not DATE_RE.fullmatch(date_text):
                raise ValueError(date_text)
            d = datetime.date(
                int(date_text[:4]), int(date_text[5:7]), int(date_text[8:])
            )
        except ValueError:
            raise LedgerError(
                3, f"{path_str}:{line}: invalid date '{quote_value(date_text)}'"
            ) from None
        try:
            amount = parse_amount(rec["amount"])
        except ValueError:
            raise LedgerError(
                3, f"{path_str}:{line}: invalid amount '{quote_value(rec['amount'])}'"
            ) from None
        result.append(Transaction(d, date_text, rec["description"], amount))
    return result


def dedup(transactions):
    seen = set()
    kept = []
    for t in transactions:
        key = (t.date, t.description, t.amount)
        if key in seen:
            continue
        seen.add(key)
        kept.append(t)
    return kept, len(transactions) - len(kept)

