"""Aggregate categorized transactions by month and category."""
from csvledger.money import CONTEXT, ZERO


def _entry(key, key_name):
    return {key_name: key, "count": 0, "income": ZERO, "expenses": ZERO}


def _add(entry, amount):
    entry["count"] += 1
    if amount > 0:
        entry["income"] = CONTEXT.add(entry["income"], amount)
    elif amount < 0:
        entry["expenses"] = CONTEXT.add(entry["expenses"], amount)


def _finish(entry):
    entry["net"] = CONTEXT.add(entry["income"], entry["expenses"])
    return entry


def aggregate(categorized):
    """categorized: iterable of (Transaction, category).

    Returns month entries (ascending) with raw Decimal sums:
    {month, count, income, expenses, net, categories: [{category, count, income, expenses, net}]}.
    """
    months = {}
    for tx, category in categorized:
        month = tx.date_text[:7]
        m = months.setdefault(month, (_entry(month, "month"), {}))
        cat = m[1].setdefault(category, _entry(category, "category"))
        _add(cat, tx.amount)
        _add(m[0], tx.amount)
    result = []
    for month in sorted(months):
        entry, cats = months[month]
        _finish(entry)
        entry["categories"] = [_finish(cats[c]) for c in sorted(cats)]
        result.append(entry)
    return result

"""Render report and categorize output as tables or JSON."""
import json

from csvledger.money import format_money


def _cell(text):
    return text.replace("\r", "\\r").replace("\n", "\\n")


def _table(headers, aligns, rows):
    rows = [[_cell(c) for c in row] for row in rows]
    widths = [
        max([len(h)] + [len(r[i]) for r in rows]) for i, h in enumerate(headers)
    ]

    def line(cells):
        parts = [
            c.ljust(w) if a == "l" else c.rjust(w)
            for c, w, a in zip(cells, widths, aligns)
        ]
        return "  ".join(parts).rstrip() + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in rows)
    return "".join(out)


def _dump(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def render_report(months, fmt):
    if fmt == "json":
        return _dump({"months": [
            {
                "month": m["month"],
                "count": m["count"],
                "income": format_money(m["income"]),
                "expenses": format_money(m["expenses"]),
                "net": format_money(m["net"]),
                "categories": [
                    {
                        "category": c["category"],
                        "count": c["count"],
                        "income": format_money(c["income"]),
                        "expenses": format_money(c["expenses"]),
                        "net": format_money(c["net"]),
                    }
                    for c in m["categories"]
                ],
            }
            for m in months
        ]})
    rows = [
        [m["month"], c["category"], str(c["count"]), format_money(c["income"]),
         format_money(c["expenses"]), format_money(c["net"])]
        for m in months
        for c in m["categories"]
    ]
    return _table(
        ["MONTH", "CATEGORY", "COUNT", "INCOME", "EXPENSES", "NET"],
        "llrrrr", rows,
    )


def render_categorize(categorized, fmt):
    rows = sorted(categorized, key=lambda tc: tc[0].date)  # stable
    if fmt == "json":
        return _dump({"transactions": [
            {
                "date": t.date_text,
                "description": t.description,
                "amount": format_money(t.amount),
                "category": cat,
            }
            for t, cat in rows
        ]})
    return _table(
        ["DATE", "AMOUNT", "CATEGORY", "DESCRIPTION"],
        "lrll",
        [[t.date_text, format_money(t.amount), cat, t.description] for t, cat in rows],
    )

import os
import pathlib
import subprocess
import sys

import pytest

REPO_ROOT = pathlib.Path(__file__).resolve().parent.parent


def write_files(directory, files):
    """Write {name: str|bytes} into directory as raw bytes (str encoded UTF-8)."""
    for name, content in files.items():
        data = content.encode("utf-8") if isinstance(content, str) else content
        (directory / name).write_bytes(data)
    return directory


def run_cli(args, cwd):
    env = {k: v for k, v in os.environ.items()
           if k not in ("PYTHONUTF8", "PYTHONIOENCODING")}
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    env["PYTHONPATH"] = str(REPO_ROOT)
    return subprocess.run(
        [sys.executable, "-m", "csvledger", *args],
        cwd=cwd, env=env, stdin=subprocess.DEVNULL,
        capture_output=True, timeout=60,
    )


